/* M109 – Accesso e protezione dei dati – version italienne, générée par outils/traduction.js depuis data.js (mêmes épreuves, même ordre). a[0] = richtige Antwort. */
window.OBJ = [{"code":"A2.2","t":"Autorizzazioni d’accesso","g":"Spiego il principio delle autorizzazioni d’accesso agli edifici e agli impianti e dei diritti d’accesso alle applicazioni e descrivo i sistemi utilizzati nella mia azienda per far rispettare queste autorizzazioni e questi diritti. (C2)","col":"teal","ic":"badge","ch":[{"k":"qcm","q":"Secondo quale criterio vengono distribuiti le chiavi o i badge in un’azienda?","a":["In funzione delle responsabilità di ciascuno","Secondo l’anzianità in azienda","Allo stesso modo a tutti i dipendenti","Secondo la scelta personale di ogni dipendente"],"ex":"Ogni dipendente riceve un accesso specifico ai locali: chiavi o badge sono distribuiti secondo le responsabilità.","ref":"Lezione 9.1"},{"k":"tf","q":"Può prestare il suo badge a un collega di fiducia senza chiedere autorizzazione.","v":false,"ex":"Regola n. 1: non affidare mai la propria chiave o il proprio badge a qualcun altro senza autorizzazione.","ref":"Lezione 9.1"},{"k":"multi","q":"Quali regole d’uso delle chiavi e dei badge figurano nel corso?","good":["Non affidare mai la propria chiave senza autorizzazione","Conservare la chiave al sicuro quando non serve","Non lasciare mai la chiave sulla porta","Non identificare l’azienda sulla chiave"],"bad":["Nascondere un doppione sotto lo zerbino","Scrivere l’indirizzo del deposito sul portachiavi"],"ex":"Il corso cita cinque regole: non affidarla, conservarla al sicuro, non lasciarla sulla porta, nessun posto ovvio (zerbino), nessuna identificazione dell’azienda.","ref":"Lezione 9.1"},{"k":"tf","q":"Si consiglia di scrivere il nome dell’azienda sulla chiave perché la si possa riportare in caso di smarrimento.","v":false,"ex":"Per motivi di sicurezza l’azienda non deve essere identificabile sulla chiave: chi la trova saprebbe dove serve.","ref":"Lezione 9.1"},{"k":"qcm","q":"Che cosa deve fare se perde una chiave dell’azienda?","a":["Segnalarlo immediatamente al datore di lavoro","Aspettare qualche giorno che ricompaia","Farne fare una copia a sue spese senza dire nulla","Prendere in prestito la chiave di un collega nel frattempo"],"ex":"Uno smarrimento va segnalato immediatamente al datore di lavoro perché prenda misure preventive.","ref":"Lezione 9.1"},{"k":"qcm","q":"Perché lo smarrimento di una chiave meccanica può costare caro?","a":["A volte bisogna sostituire tutte le serrature che apre","La chiave stessa è fabbricata in un metallo prezioso","L’assicurazione rifiuta sempre di coprire il dipendente","L’azienda deve chiudere finché non la si ritrova"],"ex":"Perdere una chiave può richiedere la sostituzione di tutte le serrature accessibili con quella chiave.","ref":"Lezione 9.1"},{"k":"fill","q":"Una chiave elettronica smarrita può essere ___, il che evita di sostituire le serrature.","a":["disattivata","duplicata","incisa","prestata"],"ex":"Nei sistemi moderni la chiave elettronica viene disattivata: nessun cambio di serrature, ma altri costi.","ref":"Lezione 9.1"},{"k":"tf","q":"Disattivare un badge elettronico smarrito non comporta alcun costo per l’azienda.","v":false,"ex":"La disattivazione evita di sostituire le serrature ma comporta altri costi (nuovo badge, gestione del sistema).","ref":"Lezione 9.1"},{"k":"qcm","q":"Come inizia generalmente l’accesso al sistema informatico dell’azienda?","a":["Con un nome utente e una password","Mostrando il proprio badge al capo","Con una firma su un registro cartaceo","Con il solo indirizzo e-mail dell’azienda"],"ex":"L’accesso al sistema informatico inizia generalmente con un nome utente e una password.","ref":"Lezione 9.5"},{"k":"qcm","q":"Perché il sistema informatico registra ogni accesso?","a":["Per rilevare qualsiasi intrusione non autorizzata","Per calcolare il salario di ogni dipendente","Per accelerare la connessione degli utenti","Per pubblicare l’attività di ogni dipendente"],"ex":"Il sistema registra ogni accesso per rilevare qualsiasi intrusione non autorizzata.","ref":"Lezione 9.5"},{"k":"fill","q":"I diritti d’accesso alle applicazioni sono attribuiti in funzione delle ___ dei dipendenti.","a":["responsabilità","preferenze","età","fasce orarie"],"ex":"Come per le chiavi, i diritti d’accesso informatici seguono le responsabilità di ciascuno.","ref":"Lezione 9.5"},{"k":"qcm","q":"Chi gestisce generalmente le reti e i sistemi informatici dell’azienda?","a":["Gli amministratori di sistema","Gli impiegati in logistica della rampa","I clienti dell’azienda","I fornitori di materiale"],"ex":"Gli amministratori di sistema gestiscono le reti; tutti i collaboratori devono comunque rispettare le regole.","ref":"Lezione 9.5"},{"k":"tf","q":"Dato che gli amministratori di sistema gestiscono l’informatica, gli impiegati in logistica non hanno alcuna regola da rispettare.","v":false,"ex":"Tutti i collaboratori, compresi gli impiegati in logistica, devono rispettare le regole stabilite.","ref":"Lezione 9.5"},{"k":"match","q":"Abbini ogni mezzo a ciò che controlla.","p":[["Chiave o badge","L’accesso ai locali e agli impianti"],["Identificativo e password","L’accesso al sistema informatico"],["Diritti d’accesso","Le applicazioni utilizzabili secondo la funzione"],["Registro degli accessi","Il rilevamento delle intrusioni"]],"ex":"Accesso fisico (chiavi, badge) e accesso informatico (identificativo, diritti, registro) seguono la stessa logica.","ref":"Lezioni 9.1 e 9.5"},{"k":"sort","q":"Accesso ai locali o accesso alle applicazioni? Classifichi.","c":["Accesso ai locali","Accesso alle applicazioni"],"it":[["Badge elettronico",0],["Chiave della porta del deposito",0],["Password",1],["Diritti attribuiti dall’amministratore",1],["Serratura del locale di stoccaggio",0],["Nome utente",1]],"ex":"Chiavi, badge e serrature proteggono gli edifici; identificativi, password e diritti proteggono le applicazioni.","ref":"Lezioni 9.1 e 9.5"},{"k":"order","q":"Perde il suo badge elettronico. Metta le tappe in ordine.","a":["Constatare lo smarrimento del badge","Segnalare lo smarrimento al datore di lavoro","Disattivazione del badge smarrito","Consegna di un nuovo badge"],"ex":"Segnalare subito permette al datore di lavoro di disattivare il badge prima che venga usato da terzi.","ref":"Lezione 9.1"},{"k":"odd","q":"Trovi l’intruso: questi comportamenti rispettano le regole delle chiavi, tranne uno.","a":["Lasciare la chiave sulla porta del locale","Riporre la chiave in un luogo sicuro","Segnalare subito una chiave smarrita","Rifiutare di prestare la chiave senza autorizzazione"],"ex":"Una chiave non deve mai restare sulla porta.","ref":"Lezione 9.1"},{"k":"case","s":"Un fattorino esterno le chiede il suo badge per andare a prendere un transpallet nel magazzino mentre lei scarica il suo camion.","q":"Che cosa fa?","a":["Rifiuta e lo accompagna o chiama un responsabile","Gli presta il badge se lo restituisce in fretta","Gli dà piuttosto il codice della porta","Lascia la porta aperta per guadagnare tempo"],"ex":"Il badge non si affida mai senza autorizzazione: l’accesso della persona esterna dev’essere controllato.","ref":"Lezione 9.1"},{"k":"case","s":"A fine giornata un collega lascia il mazzo di chiavi del deposito appeso alla serratura «per la squadra del mattino».","q":"Qual è il problema?","a":["Chiunque può entrare: una chiave non resta mai sulla porta","Nessuno, se la squadra del mattino arriva prima di tutti gli altri","Il mazzo rischia solo di consumarsi o di piegarsi","Sarebbe stato meglio nasconderlo sotto lo zerbino d’entrata"],"ex":"Non lasciare mai una chiave sulla porta, né in un posto ovvio come lo zerbino.","ref":"Lezione 9.1"},{"k":"case","s":"Lunedì mattina constata che la chiave del locale delle merci di valore è sparita da venerdì. Pensa di ritrovarla a casa stasera.","q":"Quale comportamento è corretto?","a":["Segnalare subito lo smarrimento al datore di lavoro","Cercare prima a casa e parlarne domani","Prendere in prestito la chiave di un collega nel frattempo","Non dire nulla finché nulla è stato rubato"],"ex":"Lo smarrimento si segnala immediatamente: il datore di lavoro deve poter prendere misure preventive senza aspettare.","ref":"Lezione 9.1"},{"k":"case","s":"La sua azienda ha serrature meccaniche. Un apprendista ha perso il passe-partout che apre tutti i locali.","q":"Quale conseguenza finanziaria è probabile?","a":["Sostituire tutte le serrature aperte da questo passe-partout","Sostituire solo la serratura dell’ufficio dell’apprendista","Nessuna, basta fare una copia della chiave","Disattivare la chiave a distanza, senza alcuna spesa"],"ex":"Una chiave meccanica non si disattiva: tutte le serrature che apre possono dover essere cambiate.","ref":"Lezione 9.1"},{"k":"case","s":"L’azienda è passata ai badge elettronici. Una collega ha perso il suo sull’autobus.","q":"Quale vantaggio del sistema moderno si applica qui?","a":["Il badge può essere disattivato senza cambiare le serrature","Il badge si distrugge da solo fuori dall’azienda","Un badge smarrito non costa mai nulla a nessuno","Il badge resta valido, nessuna misura è utile"],"ex":"Le chiavi elettroniche si disattivano, il che evita la sostituzione delle serrature (ma comporta altri costi).","ref":"Lezione 9.1"},{"k":"case","s":"Un nuovo impiegato in logistica scopre che non può aprire il modulo contabilità del software di gestione, mentre la sua capa vi ha accesso.","q":"Come lo si spiega?","a":["I diritti d’accesso dipendono dalle responsabilità","Il suo account è stato per forza piratato","Il software è riservato ai dipendenti anziani","Deve usare la password della sua capa"],"ex":"I diritti d’accesso sono attribuiti in funzione delle responsabilità di ogni dipendente.","ref":"Lezione 9.5"},{"k":"case","s":"Il suo caposquadra, assente, le chiede al telefono di connettersi con il suo identificativo per convalidare un ordine urgente.","q":"Quale risposta è la più professionale?","a":["Rifiutare e chiedere che le vengano attribuiti i diritti necessari","Accettare, dato che è il suo superiore diretto a chiederlo","Accettare e annotare la sua password per la prossima volta","Convalidare con il proprio account aggirando il controllo"],"ex":"Ognuno lavora con i propri diritti: usare l’account di un altro falsa il registro degli accessi e aggira le autorizzazioni.","ref":"Lezione 9.5"},{"k":"case","s":"Il servizio informatico segnala diversi tentativi di connessione con il suo identificativo alle 3 del mattino.","q":"Grazie a che cosa sono stati individuati questi tentativi?","a":["Il sistema registra ogni accesso","Dei colleghi sorvegliano gli schermi di notte","La password invia un SMS al direttore","Il badge d’entrata blocca il computer"],"ex":"Ogni accesso è registrato, il che permette di rilevare un’intrusione non autorizzata.","ref":"Lezione 9.5"},{"k":"case","s":"Una persona sconosciuta con un gilet da lavoro la segue da vicino per passare la porta di sicurezza che lei ha appena aperto con il suo badge.","q":"Che cosa fa?","a":["Chiederle gentilmente il badge o indirizzarla all’accoglienza","Lasciarla passare visto che porta un gilet dell’azienda","Tenerle la porta aperta per restare gentile e rapido","Prestarle il suo badge perché possa circolare da sola"],"ex":"Ogni persona deve passare con il proprio accesso; un visitatore passa dall’accoglienza. (Buona pratica non nel materiale del corso.)","ref":"Non nel materiale del corso · controllo degli accessi"},{"k":"case","s":"Un amico le propone di incidere «Logistik AG – deposito nord» sul suo portachiavi per non confondere più le chiavi.","q":"Perché rifiuta?","a":["Una chiave smarrita identificata indica dove può servire","L’incisione rovina la chiave e finisce per bloccare la serratura","Solo il responsabile ha il diritto di scrivere su una chiave","Una chiave incisa non è più coperta dall’assicurazione"],"ex":"L’azienda non deve essere identificabile sulla chiave, per motivi di sicurezza.","ref":"Lezione 9.1"},{"k":"case","s":"Lascia l’azienda alla fine del mese. Le restano un badge, due chiavi e il suo account informatico.","q":"Che cosa deve succedere?","a":["Restituire tutto e far eliminare i suoi accessi","Tenere il badge per ricordo, prima o poi sarà disattivato","Dare le chiavi al suo successore senza dirlo","Tenere attivo il suo account per ogni evenienza"],"ex":"Gli accessi seguono le responsabilità: senza funzione, niente più accessi. (Buona pratica non nel materiale del corso.)","ref":"Non nel materiale del corso · gestione degli accessi"}]},{"code":"A2.3","t":"Sicurezza informatica","g":"Spiego come utilizzo sistematicamente i mezzi informatici e come proteggo l’azienda dai pericoli legati in particolare all’uso di Internet (sicurezza dei dati, attacchi di pirati, virus, phishing, ecc.). (C2)","col":"indigo","ic":"lock","ch":[{"k":"num","q":"Secondo il corso, qual è la lunghezza minima di una password efficace?","n":12,"tol":0,"u":"caratteri","ex":"Il corso fissa una lunghezza minima di 12 caratteri.","ref":"Lezione 9.5.1"},{"k":"num","q":"Secondo il corso, ogni quanti mesi almeno si raccomanda di cambiare la password?","n":3,"tol":0,"u":"mesi","ex":"Il corso raccomanda un cambio almeno ogni tre mesi.","ref":"Lezione 9.5.1"},{"k":"multi","q":"Quali regole deve rispettare una password sicura secondo il corso?","good":["Almeno 12 caratteri","Maiuscole e minuscole","Cifre e caratteri speciali","Una password unica per account"],"bad":["Contenere la propria data di nascita","Essere identica su tutti gli account"],"ex":"Nessuna informazione personale e una password diversa per ogni account.","ref":"Lezione 9.5.1"},{"k":"tf","q":"«Marie1990» è una buona password, perché contiene una maiuscola, delle minuscole e delle cifre.","v":false,"ex":"È troppo corta (9 caratteri) e contiene informazioni personali (nome, anno).","ref":"Lezione 9.5.1"},{"k":"qcm","q":"Quale di queste password rispetta meglio le regole del corso?","a":["T4p!s-Rouge#Quai27","azerty12345678","Logistica2024!","Pierre-12.05.1998"],"ex":"Lunga, mescolata e senza sequenze né informazioni personali. «azerty» è una sequenza prevedibile, la data di nascita è personale.","ref":"Lezione 9.5.1"},{"k":"fill","q":"Per una sicurezza rafforzata, attivi l’autenticazione a ___ fattori.","a":["due","un solo","dieci","nessun"],"ex":"L’autenticazione a due fattori aggiunge una seconda prova alla password.","ref":"Lezione 9.5.1"},{"k":"qcm","q":"Quale strumento raccomanda il corso per gestire password uniche?","a":["Un gestore di password","Un quaderno incollato sotto la tastiera","La stessa password ovunque","Un file di testo sul desktop"],"ex":"Il corso consiglia un gestore di password (comparatore linkato nella lezione).","ref":"Lezione 9.5.1"},{"k":"match","q":"Abbini ogni motivo del corso a ciò che evita.","p":[["Contro la forza bruta","Indovinare il codice con un programma automatico"],["Contro la pirateria dell’account","Perdita di dati sensibili da un account compromesso"],["Password unica","Effetto domino dopo la fuga di dati di un sito"],["Contro il furto d’identità","Uso fraudolento delle sue informazioni"]],"ex":"Il corso dà quattro motivi per rispettare le norme sulle password.","ref":"Lezione 9.5.1"},{"k":"qcm","q":"Che cos’è un attacco a forza bruta?","a":["Provare automaticamente moltissime combinazioni","Rompere il computer per rubare fisicamente il disco rigido","Minacciare un dipendente perché riveli il suo codice d’accesso","Staccare la corrente del server per bloccare l’azienda"],"ex":"Gli attaccanti usano metodi automatizzati per indovinare o craccare i codici d’accesso.","ref":"Lezione 9.5.1"},{"k":"tf","q":"Usare la stessa password su diversi account aumenta il rischio in caso di fuga di dati su un sito.","v":true,"ex":"Con password uniche, una fuga di dati su un sito non compromette gli altri account.","ref":"Lezione 9.5.1"},{"k":"odd","q":"Trovi l’intruso: queste pratiche rafforzano la sicurezza, tranne una.","a":["Usare la sequenza «123456» ovunque","Attivare l’autenticazione a due fattori","Usare un gestore di password","Cambiare regolarmente la password"],"ex":"Le sequenze semplici o prevedibili sono da escludere.","ref":"Lezione 9.5.1"},{"k":"qcm","q":"A che cosa serve un sito come haveibeenpwned.com, citato nella lezione?","a":["Verificare se la sua e-mail figura in una fuga di dati","Creare un indirizzo e-mail anonimo per gli acquisti online","Bloccare automaticamente tutti i virus del computer","Cambiare regolarmente la password al posto suo"],"ex":"La lezione lo presenta sotto «La sua e-mail è in pericolo?».","ref":"Lezione 9.5 · link utili"},{"k":"qcm","q":"Secondo il corso, che cosa garantisce il rispetto delle norme sulle password?","a":["La confidenzialità, l’integrità e la disponibilità dei dati","La velocità della rete e delle stampanti dell’azienda","La gratuità di tutti i software usati in azienda","L’eliminazione dei backup diventati inutili ogni giorno"],"ex":"Il corso conclude: confidenzialità, integrità e disponibilità dei dati, e fiducia degli utenti.","ref":"Lezione 9.5.1"},{"k":"tf","q":"L’autenticazione a due fattori chiede, oltre alla password, una seconda prova, per esempio un codice ricevuto sul telefono.","v":true,"ex":"Anche se la password viene rubata, il pirata non può connettersi senza il secondo fattore.","ref":"Lezione 9.5.1"},{"k":"multi","q":"Quali indizi possono segnalare un’e-mail di phishing?","good":["Urgenza o minaccia per metterle fretta","Indirizzo del mittente insolito","Richiesta dei dati della carta di credito","Link verso un sito dal nome strano"],"bad":["Messaggio atteso di un collega, senza link né allegato"],"img":"mail","ex":"Pressione, mittente dubbio, richiesta di dati sensibili e link sospetto sono i segnali classici. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"qcm","q":"In questa e-mail, quale elemento rivela meglio un tentativo di phishing?","a":["Il mittente e il link usano domini insoliti","Il messaggio è scritto in italiano e inizia con «Gentile cliente»","L’indirizzo del destinatario dell’e-mail termina con .ch","Il testo del messaggio contiene un pulsante di colore blu"],"img":"mail","ex":"I domini «.xyz» e «.top», senza rapporto con un vero trasportatore, tradiscono il tentativo. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"sort","q":"Comportamento sicuro o rischioso? Classifichi.","c":["Sicuro","Rischioso"],"it":[["Bloccare lo schermo lasciando la postazione",0],["Inserire una chiavetta USB trovata nel parcheggio",1],["Installare gli aggiornamenti convalidati dall’informatica",0],["Annotare la password su un post-it",1],["Verificare il mittente prima di aprire un allegato",0],["Disattivare l’antivirus che rallenta il PC",1]],"ex":"Questi riflessi completano le regole sulle password del corso. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"match","q":"Abbini ogni minaccia alla sua descrizione.","p":[["Phishing","Falso messaggio per rubare le credenziali"],["Virus","Programma che infetta e danneggia i file"],["Ransomware","Cifra i dati ed esige un riscatto"],["Pirata","Persona che si introduce senza diritto in un sistema"]],"ex":"Le minacce citate nell’obiettivo A2.3. (Definizioni non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"order","q":"Ha digitato la sua password su una pagina sospetta. Metta le reazioni in ordine.","a":["Non digitare più nulla sulla pagina aperta","Avvisare immediatamente il servizio informatico","Cambiare la password interessata","Sorvegliare l’account nei giorni seguenti"],"ex":"Fermarsi, avvisare, cambiare, sorvegliare: più la reazione è rapida, più il danno è limitato. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"case","s":"Un collega sceglie come password il nome del suo cane seguito dal suo anno di nascita.","q":"Quale regola non rispetta?","a":["Evitare le informazioni personali","Cambiare password ogni giorno","Usare solo cifre","Non usare mai minuscole"],"ex":"Le informazioni personali (nomi, date) sono facili da indovinare.","ref":"Lezione 9.5.1"},{"k":"case","s":"Per non dimenticare nulla, un’apprendista usa la stessa password per la posta elettronica, il software di magazzino e il suo account di negozio online.","q":"Quale rischio corre?","a":["Una fuga di dati su un solo sito apre tutti i suoi account","Nessuno, finché la password supera 12 caratteri","Il suo computer rallenterà a forza di connettersi","Non potrà più ricevere e-mail professionali"],"ex":"Una password unica per account limita i danni di una fuga di dati.","ref":"Lezione 9.5.1"},{"k":"case","s":"Un collega ha incollato la sua password sullo schermo della postazione di inserimento ordini «per la squadra di notte».","q":"Che cosa consiglia?","a":["Togliere il biglietto e far creare un accesso per utente","Ricopiare il biglietto in un cassetto chiuso a chiave nella stessa postazione","Riscrivere la password più piccola perché non la si legga","Lasciare il biglietto, visto che serve solo alla squadra di notte"],"ex":"Ogni utente ha il proprio accesso, attribuito secondo le sue responsabilità; una password non si espone.","ref":"Lezione 9.5"},{"k":"case","s":"Trova una chiavetta USB con la scritta «Salari 2026» nel parcheggio dell’azienda.","q":"Che cosa fa?","a":["Consegnarla all’informatica senza inserirla","Inserirla per ritrovare il proprietario","Inserirla in un vecchio PC del magazzino","Tenerla per sé o gettarla nella spazzatura"],"ex":"Una chiavetta USB sconosciuta può contenere un programma malevolo: non la si inserisce mai. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"case","s":"Un «tecnico Microsoft» la chiama e le chiede la password per riparare un problema urgente sulla sua postazione.","q":"Quale reazione è corretta?","a":["Non darla mai e avvisare l’informatica","Darla, perché conosce il nome dell’azienda","Darla solo se richiama una seconda volta","Inviarla per e-mail piuttosto che al telefono"],"ex":"Nessun servizio serio chiede la sua password. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"case","s":"Il software di gestione del magazzino propone un aggiornamento di sicurezza convalidato dal servizio informatico.","q":"Perché installarlo?","a":["Corregge falle sfruttabili dai pirati","Rende inutile la password","Elimina l’obbligo di fare backup","Accelera solo la stampa delle etichette"],"ex":"Gli aggiornamenti chiudono falle note agli attaccanti. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"case","s":"Una mattina tutti i file del server sono illeggibili e un messaggio chiede un pagamento in criptovaluta per recuperarli.","q":"Di quale tipo di attacco si tratta?","a":["Un ransomware","Un attacco a forza bruta","Un guasto della stampante","Un phishing via SMS"],"ex":"Il ransomware cifra i dati ed esige un riscatto; si avvisa l’informatica e non si paga. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"case","s":"Deve lasciare la sua postazione dieci minuti per aiutare alla rampa di carico. La sua sessione del software di magazzino è aperta.","q":"Che cosa fa?","a":["Bloccare lo schermo prima di partire","Lasciare la sessione aperta, è rapido","Spegnere solo lo schermo","Chiedere all’autista di sorvegliare il PC"],"ex":"Una sessione aperta permette a chiunque di agire a suo nome. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"case","s":"La sua azienda attiva l’autenticazione a due fattori. Un collega brontola: «La mia password basta!»","q":"Quale argomento gli dà?","a":["Anche con la sua password rubata, un pirata non potrà connettersi","Poi non avrà mai più bisogno di cambiare la password","Sostituisce l’antivirus installato sul suo computer di lavoro","Lo autorizza a condividere la password con la sua squadra"],"ex":"Il secondo fattore blocca l’accesso anche se la password è nota.","ref":"Lezione 9.5.1"},{"k":"case","s":"La ricezione riceve un’e-mail da un trasportatore sconosciuto: esige CHF 2.99 entro 24 ore per sbloccare un pacco, con un pulsante «Paga ora».","q":"Qual è la reazione giusta?","a":["Non cliccare e segnalare l’e-mail all’informatica","Pagare i 2.99 franchi, l’importo è basso","Rispondere per chiedere più informazioni","Inoltrare l’e-mail a tutti i colleghi per un parere"],"img":"mail","ex":"Urgenza, piccolo importo e richiesta della carta di credito: è phishing. Lo si segnala (in Svizzera anche all’NCSC). (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"},{"k":"case","s":"Un SMS la informa che un pacco attende il pagamento di «spese di 1.50 CHF», con un link abbreviato.","q":"Come lo tratta?","a":["Non cliccare, cancellare o segnalare il messaggio","Cliccare sul link per verificare se il pacco esiste","Pagare le spese, l’importo è davvero simbolico","Rispondere «STOP» per non ricevere più messaggi"],"ex":"Il phishing passa anche via SMS; rispondere conferma che il suo numero è attivo. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · buone pratiche NCSC"}]},{"code":"B1.5","t":"Segreti e protezione dei dati","g":"Spiego le basi e gli effetti della protezione dei dati e della sfera privata nonché del segreto postale. (C2)","col":"violet","ic":"mailx","ch":[{"k":"qcm","q":"Quale articolo del Codice penale punisce la violazione del segreto epistolare?","a":["Art. 179 CP","Art. 321ter CP","Art. 321a CO","Art. 6 LPD"],"ex":"L’art. 179 CP, sotto «Reati contro l’onore e contro la sfera personale riservata».","ref":"Lezione 9.2 · CP 179"},{"k":"qcm","q":"Quale articolo del Codice penale punisce la violazione del segreto postale?","a":["Art. 321ter CP","Art. 179 CP","Art. 162 CP","Art. 321a CO"],"ex":"Art. 321ter CP: violazione del segreto postale e del segreto delle telecomunicazioni.","ref":"Lezione 9.3 · CP 321ter"},{"k":"qcm","q":"Dove è regolato il segreto d’affari del dipendente, secondo il corso?","a":["Nel Codice delle obbligazioni (art. 321a CO)","Nella legge sulla circolazione stradale","Nel regolamento interno della Posta","Nella Costituzione cantonale"],"ex":"Il dovere di diligenza e di fedeltà dell’art. 321a CO include la discrezione sui segreti d’affari.","ref":"Lezione 9.4 · CO 321a"},{"k":"tf","q":"Il segreto epistolare si applica solo alla sfera professionale.","v":false,"ex":"Si applica anche alla sfera privata: i privati non devono occuparsi della posta degli altri.","ref":"Lezione 9.2"},{"k":"qcm","q":"Che cos’è un reato perseguibile a querela di parte?","a":["Le autorità indagano solo se la persona lesa lo chiede","Le autorità indagano non appena vengono a conoscenza dei fatti","Solo il datore di lavoro dell’autore può sporgere querela penale","Il reato è giudicato internamente dall’azienda stessa"],"ex":"Al contrario, un reato perseguibile d’ufficio obbliga le autorità a indagare di propria iniziativa.","ref":"Lezione 9.2"},{"k":"match","q":"Abbini ogni nozione alla sua definizione.","p":[["Reato a querela di parte","Indagine su richiesta della persona lesa"],["Reato perseguibile d’ufficio","Indagine non appena l’autorità viene a sapere dei fatti"],["Segreto epistolare","Protegge il contenuto di plichi e pacchi chiusi"],["Segreto postale","Protegge anche il mittente e il destinatario"]],"ex":"Il segreto postale va oltre il contenuto: protegge anche l’identità delle persone e la frequenza degli invii.","ref":"Lezioni 9.2 e 9.3"},{"k":"multi","q":"Che cosa protegge il segreto postale?","good":["Il contenuto degli invii","L’identità del mittente","L’identità del destinatario","La frequenza degli invii"],"bad":["Le tariffe ufficiali della Posta","L’indirizzo pubblico di un ufficio postale"],"ex":"Il segreto postale impedisce qualsiasi divulgazione dell’identità delle persone o della frequenza degli invii.","ref":"Lezione 9.3"},{"k":"fill","q":"Il segreto postale va oltre la semplice confidenzialità delle ___.","a":["lettere","fatture","francobolli","tariffe"],"ex":"Comprende anche la protezione del mittente e del destinatario.","ref":"Lezione 9.3"},{"k":"tf","q":"Il segreto postale deve essere rispettato anche dopo la fine del rapporto di lavoro.","v":true,"ex":"La violazione resta punibile dopo la fine del rapporto di lavoro (art. 321ter cpv. 3 CP).","ref":"Lezione 9.3 · CP 321ter"},{"k":"multi","q":"Quali informazioni cita il corso come altamente private?","good":["Gli atti giudiziari","Le notifiche di pagamento","Il versamento dell’AVS"],"bad":["L’orario d’apertura di un deposito","Il meteo del giorno"],"ex":"Il corso dà questi esempi: atti giudiziari, notifiche di pagamento, versamento dell’AVS.","ref":"Lezione 9.3"},{"k":"qcm","q":"Per quanto tempo il dipendente deve mantenere i segreti di fabbricazione e d’affari?","a":["Durante il contratto e dopo, se l’interesse del datore di lavoro lo esige","Solo durante il periodo di prova, poi il segreto cade","Unicamente durante le sue ore di lavoro effettive","Fino alla fine dell’anno civile in cui termina il contratto"],"ex":"L’obbligo di discrezione continua dopo la fine del contratto, nella misura in cui lo esigono gli interessi legittimi del datore di lavoro.","ref":"Lezione 9.4 · CO 321a al. 4"},{"k":"fill","q":"Il lavoratore esegue con diligenza il lavoro affidatogli e salvaguarda ___ gli interessi legittimi del datore di lavoro.","a":["fedelmente","parzialmente","occasionalmente","liberamente"],"ex":"È il dovere di diligenza e di fedeltà (art. 321a cpv. 1 CO).","ref":"Lezione 9.4 · CO 321a"},{"k":"sort","q":"Segreto postale o segreto d’affari? Classifichi.","c":["Segreto postale","Segreto d’affari"],"it":[["Identità del destinatario di una raccomandata",0],["Ricetta di fabbricazione di un prodotto",1],["Frequenza degli invii di un cliente",0],["Prezzi negoziati con i fornitori",1],["Contenuto di una lettera trasportata",0],["Progetto di un nuovo sito logistico",1]],"ex":"Il segreto postale protegge gli invii e le persone; il segreto d’affari protegge le informazioni del datore di lavoro.","ref":"Lezioni 9.3 e 9.4"},{"k":"odd","q":"Trovi l’intruso: questi elementi rientrano in un segreto protetto, tranne uno.","a":["L’indirizzo pubblico della sede dell’azienda","Il contenuto di un pacco chiuso","Il mittente di un atto giudiziario","I margini commerciali del datore di lavoro"],"ex":"L’indirizzo della sede è pubblico; gli altri tre sono protetti (segreto epistolare, segreto postale, segreto d’affari).","ref":"Lezioni 9.2 a 9.4"},{"k":"order","q":"Un collega apre senza diritto un plico chiuso destinato a un’altra persona. Metta il seguito in ordine (art. 179 CP).","a":["Il plico viene aperto senza diritto","Il destinatario scopre l’apertura","Il destinatario sporge querela","Le autorità aprono un’indagine","Il giudice può pronunciare una multa"],"ex":"È un reato a querela di parte: senza querela della persona lesa, nessuna indagine.","ref":"Lezione 9.2 · CP 179"},{"k":"qcm","q":"Da quando è in vigore la nuova legge federale sulla protezione dei dati (nLPD)?","a":["Dal 1° settembre 2023","Dal 1° gennaio 2000","Dal 1° gennaio 2026","Dal 1° luglio 1992"],"ex":"La LPD totalmente riveduta è entrata in vigore il 1° settembre 2023, senza periodo transitorio. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · nLPD (in vigore dal 1.9.2023)"},{"k":"multi","q":"Quali sono i principi del trattamento dei dati secondo la nLPD?","good":["Liceità","Buona fede","Proporzionalità","Finalità","Sicurezza"],"bad":["Redditività","Pubblicità"],"ex":"Art. 6 e 8 LPD: liceità, buona fede, proporzionalità, finalità, trasparenza, esattezza e sicurezza. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · nLPD (in vigore dal 1.9.2023)"},{"k":"tf","q":"La nLPD protegge i dati delle persone fisiche, ma non più quelli delle persone giuridiche (aziende).","v":true,"ex":"Dal 2023 solo i dati delle persone fisiche sono protetti dalla LPD. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · nLPD (in vigore dal 1.9.2023)"},{"k":"case","s":"Al servizio posta interno, una collega nota una busta dell’Ufficio d’esecuzione indirizzata a un collega e ne parla durante la pausa.","q":"Quale principio viola?","a":["La discrezione sul mittente e sul destinatario di un invio","Nessun principio, dato che non ha aperto la busta","Solo le regole di cortesia tra colleghi","Il segreto d’affari proprio dell’Ufficio d’esecuzione"],"ex":"La protezione va oltre il contenuto: l’identità del mittente e del destinatario non si divulga.","ref":"Lezione 9.3"},{"k":"case","s":"Durante il suo giro nota che un cliente riceve ogni mese una lettera della cassa AVS. Un vicino le chiede se riceve una rendita.","q":"Che cosa risponde?","a":["Non dà alcuna informazione sulla posta dei clienti","Conferma, dato che non è davvero un segreto","Risponde solo se il vicino è anche suo amico","Gli consiglia di guardare lui stesso nella bucalettere"],"ex":"Il corso cita proprio il versamento dell’AVS come informazione confidenziale.","ref":"Lezione 9.3"},{"k":"case","s":"Il suo coinquilino apre «per curiosità» una lettera chiusa indirizzata a lei.","q":"Si applica il segreto epistolare?","a":["Sì, si applica anche alla sfera privata","No, riguarda solo i dipendenti della Posta","No, riguarda solo i pacchi","Sì, ma solo per una lettera di un tribunale"],"ex":"Il segreto epistolare vale anche tra privati.","ref":"Lezione 9.2 · CP 179"},{"k":"case","s":"Un ex dipendente di un centro di smistamento postale, partito da due anni, racconta quali vicini ricevono atti giudiziari.","q":"Può essere perseguito?","a":["Sì, la violazione resta punibile dopo il rapporto di lavoro","No, il segreto termina con il contratto di lavoro","No, perché non lavora più per la Posta","Solo se ha aperto lui stesso gli invii"],"ex":"Il segreto postale continua ad applicarsi dopo la fine del rapporto di lavoro.","ref":"Lezione 9.3 · CP 321ter"},{"k":"case","s":"Una cliente scopre che un dipendente della ricezione ha aperto un plico chiuso a lei destinato, ma non vuole sporgere querela.","q":"Che cosa succede sul piano penale (art. 179 CP)?","a":["Nulla: è un reato a querela di parte","La polizia indaga comunque","Il dipendente viene automaticamente incarcerato","L’azienda paga una multa fissa"],"ex":"Senza querela della persona lesa, le autorità non indagano.","ref":"Lezione 9.2 · CP 179"},{"k":"case","s":"Al bar, un amico le chiede quanto fattura la sua azienda per lo stoccaggio al suo cliente più grande.","q":"Che cosa fa?","a":["Rifiuta: è un segreto d’affari","Risponde, dato che è un amico","Dà solo una cifra approssimativa","Risponde se il periodo di prova è finito"],"ex":"Le informazioni commerciali del datore di lavoro sono confidenziali (art. 321a CO).","ref":"Lezione 9.4 · CO 321a"},{"k":"case","s":"Passa a un concorrente. Il suo nuovo capo le chiede l’elenco dei clienti del suo ex datore di lavoro.","q":"Come reagire?","a":["Rifiutare: la discrezione continua dopo il contratto","Accettare, il vecchio contratto non la vincola più","Accettare se l’elenco ha più di un anno","Darlo a voce piuttosto che per iscritto"],"ex":"Il dovere di mantenere i segreti d’affari sussiste dopo la fine del contratto.","ref":"Lezione 9.4 · CO 321a al. 4"},{"k":"case","s":"Su un social network un apprendista pubblica un lungo messaggio che critica apertamente la sua azienda e i suoi capi.","q":"Che cosa raccomanda il corso?","a":["Dar prova di riserbo ed evitare le critiche pubbliche","Criticare pubblicamente per far cambiare le cose in fretta","Pubblicare solo con uno pseudonimo per restare discreto","Citare l’azienda perché risponda pubblicamente"],"ex":"Il corso raccomanda riserbo: una critica pubblica lascia un’impressione negativa.","ref":"Lezione 9.4"},{"k":"case","s":"La sua azienda annota la data di nascita di ogni visitatore del deposito «per ogni evenienza», senza dirgli perché.","q":"Quali principi della nLPD sono toccati?","a":["La proporzionalità e la buona fede (trasparenza)","Solo la redditività dell’azienda","Nessuno, i visitatori non sono clienti","Solo il segreto postale e quello d’affari"],"ex":"Si raccolgono solo i dati necessari, per uno scopo riconoscibile dalla persona. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · nLPD (in vigore dal 1.9.2023)"},{"k":"case","s":"Un autista-fattorino fotografa un bollettino di consegna firmato da un cliente e lo pubblica in una chat di gruppo per scherzare sulla sua firma.","q":"Qual è il problema?","a":["Divulga dati personali senza motivo","Nessuno, una firma non è un dato","Solo la qualità della foto è un problema","È permesso in un gruppo privato"],"ex":"Nome, indirizzo e firma sono dati personali: diffonderli senza motivo viola la sfera privata del cliente. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · nLPD (in vigore dal 1.9.2023)"}]},{"code":"B1.6","t":"Conseguenze nella pratica","g":"Spiego le conseguenze delle disposizioni legali relative alla protezione dei dati e della sfera privata e al segreto postale per l’attività pratica, nonché una conseguenza per il cliente e per l’azienda in caso di violazione. (C2)","col":"coral","ic":"balance","ch":[{"k":"pickimg","q":"Il servizio posta può aprire questa busta senza esitare. Quale?","a":["env_a","env_b","env_c","env_d"],"ex":"Indirizzata solo all’azienda: può essere aperta.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"pickimg","q":"Quale non deve MAI essere aperta dal servizio posta?","a":["env_d","env_a","env_b","env_c"],"ex":"La dicitura «Personale/confidenziale» vieta qualsiasi apertura.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"pickimg","q":"Quale si apre solo se il signor Gugger l’ha espressamente desiderato?","a":["env_c","env_a","env_d"],"ex":"Il nome della persona figura prima dell’azienda: si apre solo se il signor Gugger l’ha espressamente desiderato.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"pickimg","q":"Quale può essere aperta su istruzione, senza avviso contrario?","a":["env_b","env_c","env_d"],"ex":"Prima l’azienda, poi «All’attenzione di»: apertura su istruzione, senza avviso contrario.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"match","q":"Abbini ogni busta alla sua regola di apertura.","p":[["A · EnterSite AG","Aprire"],["B · All’attenzione di R. Gugger","Aprire su istruzione, senza avviso contrario"],["C · Signor Reto Gugger, EnterSite AG","Solo se il signor Gugger l’ha desiderato"],["D · Personale/confidenziale","Non aprire mai"]],"img":"env","ex":"Più la persona è messa in evidenza nell’indirizzo, più la posta è considerata personale.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"sort","q":"Il servizio posta può aprire questa posta? Classifichi.","c":["Può essere aperta","Non senza l’accordo del destinatario"],"it":[["Indirizzo: solo EnterSite AG",0],["EnterSite AG, all’attenzione di R. Gugger",0],["Signor R. Gugger, EnterSite AG",1],["Dicitura «Personale/confidenziale»",1]],"img":"env","ex":"A e B possono essere aperte (B su istruzione); C solo se il signor Gugger l’ha desiderato; D mai.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"tf","q":"Quando il nome della persona figura prima di quello dell’azienda, la lettera è considerata personale.","v":true,"ex":"«Signor Reto Gugger, EnterSite AG»: si apre solo se il signor Gugger l’ha espressamente desiderato.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"tf","q":"Il segreto epistolare riguarda anche i collaboratori di un servizio posta interno all’azienda.","v":true,"ex":"Il contenuto di lettere e pacchi non li riguarda, così come non riguarda i dipendenti della Posta.","ref":"Lezione 9.2"},{"k":"qcm","q":"Quale sanzione prevede l’art. 179 CP per la violazione del segreto epistolare?","a":["Una multa, a querela di parte","Una pena detentiva di dieci anni","Un semplice avvertimento orale","Nessuna, è una regola morale"],"ex":"Art. 179 CP: «è punito, a querela di parte, con la multa».","ref":"Lezione 9.2 · CP 179"},{"k":"qcm","q":"Che cosa rischia un dipendente di un servizio postale che viola il segreto postale?","a":["Una pena detentiva o una pena pecuniaria","Solo un biasimo scritto del suo capo servizio","Una multa disciplinare di 20 franchi, pagabile sul posto","Proprio nulla se nel frattempo ha lasciato l’impiego"],"ex":"Il corso parla di pene detentive o pecuniarie, anche dopo la fine del rapporto di lavoro (art. 321ter CP).","ref":"Lezione 9.3 · CP 321ter"},{"k":"num","q":"Pena detentiva massima, in anni, prevista dall’art. 321ter CP?","n":3,"tol":0,"u":"anni","ex":"Art. 321ter cpv. 1 CP: pena detentiva sino a tre anni o pena pecuniaria. (Cifra non nel materiale del corso.)","ref":"Non nel materiale del corso · CP 321ter cpv. 1"},{"k":"num","q":"Importo massimo, in franchi, della multa prevista dalla nLPD per alcune violazioni intenzionali?","n":250000,"tol":0,"u":"CHF","ex":"La nLPD prevede multe fino a CHF 250 000, inflitte alla persona responsabile. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · nLPD (in vigore dal 1.9.2023)"},{"k":"qcm","q":"Secondo il corso, che cosa può fare il datore di lavoro contro un dipendente che non mantiene i segreti d’affari?","a":["Denunciarlo","Togliergli il diritto di voto","Privarlo delle vacanze legali","Nulla, la legge non lo prevede"],"ex":"Chi non rispetta questa regola può essere denunciato dal suo datore di lavoro.","ref":"Lezione 9.4"},{"k":"multi","q":"Quali conseguenze può avere per l’azienda una violazione della protezione dei dati?","good":["Perdita di fiducia dei clienti","Danno alla sua immagine","Querela o sanzione penale","Perdita di clienti o di contratti"],"bad":["Aumento automatico delle sue vendite"],"ex":"La fiducia è al centro dell’attività logistica: una fuga di dati la distrugge in fretta.","ref":"Obiettivo B1.6"},{"k":"multi","q":"Quali conseguenze per il cliente i cui dati sono stati divulgati?","good":["Lesione della sua sfera privata","Divulgazione di informazioni sensibili (esecuzioni, denaro)","Rischio di frode o di furto d’identità"],"bad":["Riduzione delle sue imposte","Consegna più rapida dei suoi pacchi"],"ex":"Il corso ricorda che password deboli espongono a frodi e furti d’identità; una divulgazione tocca la sfera privata.","ref":"Lezioni 9.3 e 9.5"},{"k":"odd","q":"Trovi l’intruso: questi gesti rispettano il segreto nella vita quotidiana, tranne uno.","a":["Commentare la posta di un cliente con un vicino","Consegnare una lettera chiusa senza leggerla","Non parlare dei clienti fuori dal lavoro","Trasmettere un plico confidenziale senza aprirlo"],"ex":"La posta dei clienti non si commenta mai con terzi.","ref":"Lezione 9.3"},{"k":"order","q":"Una busta «Personale/confidenziale» è stata aperta per errore al servizio posta interno. Metta le azioni in ordine.","a":["Smettere immediatamente di leggere","Richiudere e annotare «aperto per errore»","Consegnare l’invio al destinatario informandolo"],"ex":"Si limita la presa di conoscenza, si segnala l’errore e si consegna l’invio. (Buona pratica non nel materiale del corso.)","ref":"Non nel materiale del corso · buona pratica"},{"k":"case","s":"Al servizio posta della EnterSite AG smista una lettera indirizzata «Signor Reto Gugger, EnterSite AG». Il signor Gugger non ha dato alcuna istruzione.","q":"Che cosa fa?","a":["Gliela trasmette chiusa","La apre per smistarla al servizio giusto","La apre e poi la richiude con cura","La rispedisce al mittente"],"img":"env","ex":"Busta C: si apre solo se il signor Gugger l’ha espressamente desiderato.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"case","s":"La sua capa le ha chiesto di aprire la posta dell’azienda durante le sue vacanze. Le arriva una lettera «Personale/confidenziale».","q":"Che cosa fa?","a":["La tiene chiusa fino al suo ritorno","La apre dato che gliel’ha chiesto","La fa aprire da un collega","La legge senza toglierla dalla busta"],"ex":"«Personale/confidenziale»: non aprire mai. L’istruzione riguarda la posta dell’azienda.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"case","s":"Arriva una lettera indirizzata «EnterSite AG, all’attenzione di Reto Gugger». Non esiste alcuna istruzione contraria.","q":"Secondo la tabella del corso, che cosa fare?","a":["Può essere aperta su istruzione","Non deve mai essere aperta","Solo se il signor Gugger l’ha desiderato","Rispedirla al mittente"],"ex":"Busta B: senza avviso contrario, si apre su istruzione.","ref":"Lezione 9.2 · tabella degli indirizzi"},{"k":"case","s":"Un fattorino racconta al ristorante che un cliente riceve molte raccomandate dell’Ufficio d’esecuzione. Il cliente viene a saperlo.","q":"Quale conseguenza per il cliente?","a":["La sua situazione finanziaria privata viene esposta","Nessuna, le raccomandate non sono confidenziali","Ottiene una dilazione di pagamento","Le sue esecuzioni vengono annullate"],"ex":"Il segreto postale protegge proprio l’identità del mittente e gli atti giudiziari.","ref":"Lezione 9.3"},{"k":"case","s":"Un cliente scopre che un fattorino ha divulgato i suoi invii dell’Ufficio d’esecuzione e racconta la vicenda sui social network.","q":"Quale conseguenza rischia l’azienda di consegne?","a":["Perdita di fiducia, danno all’immagine, partenza di clienti","Un aumento degli ordini grazie alla pubblicità gratuita","Nessuna, perché solo il fattorino è coinvolto nella vicenda","Un sussidio pubblico per formare meglio il fattorino"],"ex":"L’azienda subisce la perdita di fiducia, oltre alla procedura contro il dipendente.","ref":"Obiettivo B1.6"},{"k":"case","s":"Un impiegato d’ufficio di un’impresa di costruzioni apre per curiosità un pacco chiuso indirizzato a un collega.","q":"Quale articolo può applicarsi?","a":["Art. 179 CP, segreto epistolare","Art. 321a CO, fedeltà del cliente","Art. 162 CP, segreto di fabbricazione","Nessuno, tra colleghi è permesso"],"ex":"Aprire senza diritto un plico o un pacco chiuso per conoscerne il contenuto: art. 179 CP.","ref":"Lezione 9.2 · CP 179"},{"k":"case","s":"Una dipendente della Posta racconta alla sua famiglia che un vicino riceve regolarmente invii da una clinica.","q":"Quale rischio penale corre?","a":["Una pena detentiva o pecuniaria (art. 321ter CP)","Una semplice multa disciplinare di 40 franchi (art. 179 CP)","Nessun rischio, dato che non ha aperto alcun invio","Solo un avvertimento interno del suo datore di lavoro"],"ex":"Divulgare informazioni sulle relazioni postali di un cliente basta, anche senza aprire l’invio.","ref":"Lezione 9.3 · CP 321ter"},{"k":"case","s":"Un magazziniere trasmette a un concorrente i prezzi d’acquisto negoziati dal suo datore di lavoro.","q":"Quale conseguenza è possibile?","a":["Il suo datore di lavoro può denunciarlo","Nessuna, i prezzi d’acquisto sono pubblici","Riceve un premio dal suo datore di lavoro","Solo il concorrente è punibile"],"ex":"Violazione del segreto d’affari (art. 321a CO): il datore di lavoro può denunciarlo.","ref":"Lezione 9.4"},{"k":"case","s":"Durante una visita del magazzino, degli allievi fotografano uno schermo che mostra nomi, indirizzi e ordini di clienti.","q":"Quale misura pratica avrebbe evitato il problema?","a":["Nascondere o bloccare gli schermi con dati di clienti","Vietare d’ora in poi qualsiasi visita dell’azienda","Mostrare i dati più piccoli sugli schermi","Niente, perché questi dati non sono dati personali"],"ex":"La sicurezza dei dati passa da gesti semplici alla postazione di lavoro. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · nLPD (in vigore dal 1.9.2023)"},{"k":"case","s":"Un collega getta bollettini di consegna con nomi, indirizzi e firme di clienti nel cestino della rampa, accessibile a tutti.","q":"Che cosa gli dice?","a":["Questi documenti si distruggono in modo sicuro (distruggidocumenti)","È corretto, sono vecchi documenti senza valore","Bisogna riciclarli con il cartone normale della rampa","Basta piegarli in due prima di gettarli"],"ex":"I dati personali si distruggono in modo sicuro quando non servono più. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · nLPD (in vigore dal 1.9.2023)"}]},{"code":"D5.3","t":"Persone autorizzate a ricevere","g":"Spiego le condizioni quadro legali relative alle persone autorizzate a ricevere merci da consegnare. (C2)","col":"amber","ic":"parcel","ch":[{"k":"qcm","q":"A chi consegna l’impiegato in logistica le merci consegnate?","a":["A una persona autorizzata a riceverle","Alla prima persona presente all’indirizzo","A un vicino qualsiasi disponibile","All’autista successivo del giro"],"ex":"Competenza d5: consegnare le merci in modo competente a una persona autorizzata.","ref":"Piano di formazione · competenza d5"},{"k":"tf","q":"Una persona che vive nella stessa economia domestica può ritirare un invio ordinario senza procura.","v":true,"ex":"Le persone della stessa economia domestica non hanno bisogno di procura (salvo atti esecutivi). (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"tf","q":"Una persona della stessa economia domestica può ritirare un atto esecutivo senza procura.","v":false,"ex":"Per gli atti esecutivi è sempre richiesta una procura. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"qcm","q":"Che cos’è una procura postale?","a":["Un’autorizzazione data a un’altra persona di ritirare invii","Una fattura emessa per un invio consegnato in ritardo","Un’assicurazione supplementare contro la perdita di un pacco","Un modulo di reclamo in caso di invio danneggiato"],"ex":"Con una procura autorizza una o più persone a ritirare i suoi invii. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"match","q":"Abbini ogni situazione alla sua regola.","p":[["Procura unica","Per un invio preciso"],["Procura permanente","Per diversi invii nel tempo"],["Consegna in proprie mani","Nessuna procura possibile"],["Stessa economia domestica","Senza procura, salvo esecuzioni"]],"ex":"Regole della Posta Svizzera. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"qcm","q":"Quale tipo di procura deve usare alla Posta un’azienda cliente?","a":["Una procura permanente","Una procura unica per telefono","Nessuna, basta il nome dell’azienda","Una semplice e-mail del direttore"],"ex":"I clienti commerciali usano una procura permanente. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"multi","q":"Quali documenti d’identità sono accettati per ritirare un invio con procura?","good":["Passaporto","Carta d’identità","Licenza di condurre svizzera","Libretto per stranieri"],"bad":["Libretto di famiglia","Fotocopia della carta d’identità"],"ex":"Originale di un documento con foto; il libretto di famiglia non è accettato. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"tf","q":"Una fotocopia della carta d’identità basta per ritirare una raccomandata con procura.","v":false,"ex":"Bisogna presentare l’originale di un documento d’identità con foto. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"fill","q":"Un invio «Consegna in proprie mani» deve essere ritirato dal destinatario ___.","a":["in persona","tramite procura","tramite un vicino","tramite la famiglia"],"ex":"Per la consegna in proprie mani non si può rilasciare alcuna procura. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"sort","q":"Ci vuole una procura? Classifichi.","c":["Senza procura","Procura necessaria","Impossibile, anche con procura"],"it":[["Coniuge della stessa economia domestica, pacco ordinario",0],["Amico, lettera raccomandata",1],["Collega, invio «Consegna in proprie mani»",2],["Figlio della stessa economia domestica, atto esecutivo",1],["Vicino, pacco Signature",1]],"ex":"Economia domestica: libero salvo esecuzioni; terzi: procura; proprie mani: solo il destinatario. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"qcm","q":"Che cosa conferma la firma della persona che riceve una raccomandata?","a":["La consegna dell’invio","Il pagamento delle spese di porto","L’apertura dell’invio","L’accordo con il contenuto della lettera"],"ex":"I mandatari confermano la ricezione con la loro firma. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"odd","q":"Trovi l’intruso: queste persone possono ricevere per lei un pacco ordinario allo sportello, tranne una.","a":["Un passante che propone di prenderlo","Il suo coniuge che vive con lei","Una persona con la sua procura permanente","Una persona con una procura unica"],"ex":"Senza legame di economia domestica né procura, nessuno è autorizzato. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"order","q":"Ritiro di una raccomandata da parte di un mandatario allo sportello: metta in ordine.","a":["Presentare l’avviso di ritiro e la procura","Mostrare l’originale di un documento d’identità con foto","Controllo dell’identità e della procura","Firma del mandatario","Consegna dell’invio"],"ex":"Si verifica l’identità, poi la firma prova la consegna. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"qcm","q":"Perché verificare l’identità per un pacco Signature o una raccomandata?","a":["Per provare la consegna alla persona giusta","Per completare le statistiche del giro","Per incassare spese supplementari","Per verificare l’età del cliente"],"ex":"Il destinatario o il mandatario deve dimostrare la sua identità. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"tf","q":"Un’amministrazione immobiliare con servizio di portineria può, grazie alla sua procura, ricevere gli atti giudiziari degli inquilini.","v":false,"ex":"La procura dei fornitori di servizi esclude atti giudiziari, esecuzioni e invii in proprie mani. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"qcm","q":"Secondo l’art. 321ter CP, quando una violazione del segreto postale non è punibile?","a":["Se è necessaria per determinare l’avente diritto","Se l’invio interessato ha uno scarso valore commerciale","Se il destinatario è assente al momento della consegna","Se il fattorino ha fretta a fine giro"],"ex":"Cpv. 4: non punibile se necessaria per determinare l’avente diritto o prevenire un danno. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · CP 321ter cpv. 4"},{"k":"case","s":"Consegna un pacco Signature. Il destinatario è assente; il vicino propone di firmare al suo posto, senza procura.","q":"Che cosa fa?","a":["Lascia un avviso di ritiro al destinatario","Lo consegna, il vicino lo conosce bene","Firma lei stesso al posto del cliente","Lo deposita davanti alla porta"],"ex":"Il vicino non è autorizzato: l’invio attende il destinatario o il suo mandatario. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"case","s":"Una donna vuole ritirare allo sportello una lettera raccomandata indirizzata a suo marito, con cui vive. Non è un atto esecutivo.","q":"Può ritirarla?","a":["Sì, la stessa economia domestica non ha bisogno di procura","No, solo il marito può ritirare una raccomandata","Sì, ma solo con una procura permanente","No, a meno che paghi delle spese"],"ex":"Stessa economia domestica: niente procura, salvo per gli atti esecutivi. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"case","s":"Un uomo vuole ritirare senza procura un precetto esecutivo indirizzato a suo fratello, con cui abita.","q":"Quale risposta è corretta?","a":["Rifiutare: per le esecuzioni è richiesta una procura","Accettare, dato che vivono entrambi nella stessa economia domestica","Accettare se presenta l’originale della sua carta d’identità","Accettare se promette di trasmetterlo la sera stessa"],"ex":"Eccezione all’economia domestica: gli atti esecutivi richiedono sempre una procura. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"case","s":"La sua azienda logistica vuole che il capo rampa ritiri ogni giorno in filiale gli invii indirizzati all’azienda.","q":"Quale soluzione scegliere?","a":["Rilasciare una procura permanente a suo nome","Dargli una procura unica per telefono","Niente, basta l’uniforme dell’azienda","Affidargli la carta d’identità del direttore"],"ex":"Per un cliente commerciale e ritiri regolari: procura permanente. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"case","s":"Per ritirare un pacco con procura, un cliente presenta una foto della sua carta d’identità sul telefono.","q":"Che cosa fa?","a":["Chiedere l’originale di un documento d’identità con foto","Accettare, perché la foto sul telefono è ben nitida","Accettare, dato che la procura è firmata correttamente","Chiedere invece il suo libretto di famiglia originale"],"ex":"È accettato solo l’originale di un documento d’identità con foto. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"case","s":"Un invio porta la dicitura «Consegna in proprie mani». La destinataria manda il suo assistente con una procura permanente.","q":"L’assistente può ritirare l’invio?","a":["No, la consegna in proprie mani esclude qualsiasi procura","Sì, la procura permanente copre tutti gli invii","Sì, se presenta la propria carta d’identità originale","Sì, a condizione che firmi due volte la ricevuta"],"ex":"Per la consegna in proprie mani il destinatario deve venire di persona. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"case","s":"Durante una consegna in azienda, la receptionist dell’accoglienza propone di firmare per un pacco indirizzato all’azienda.","q":"È accettabile?","a":["Sì, se l’azienda l’ha autorizzata a ricevere le merci","No, solo il direttore dell’azienda ha il diritto di firmare","No, un’azienda non può ricevere alcun pacco Signature","Sì, qualsiasi visitatore presente all’accoglienza può firmare"],"ex":"In azienda la merce si consegna a una persona autorizzata dall’azienda.","ref":"Piano di formazione · competenza d5"},{"k":"case","s":"Un fattorino di fretta deposita un pacco Signature davanti alla porta e convalida lui stesso il terminale.","q":"Quale rischio crea?","a":["La consegna non è provata, il pacco può sparire","Nessuno, il cliente guadagna tempo e sarà soddisfatto","Il pacco Signature diventa così un invio ordinario","Solo il destinatario è responsabile del suo pacco"],"ex":"La firma prova la consegna alla persona giusta; senza di essa il fattorino e l’azienda sono esposti.","ref":"Piano di formazione · competenza d5"},{"k":"case","s":"Alla consegna di una raccomandata, una persona afferma di essere la destinataria, ma il nome sul suo documento d’identità non corrisponde.","q":"Che cosa fa?","a":["Non consegnare l’invio e lasciare un avviso di ritiro","Consegnarlo, dato che conosce il contenuto dell’invio","Consegnarlo contro una firma e una mancia","Aprire l’invio davanti a lei per verificare il contenuto"],"ex":"L’identità dev’essere dimostrata: in caso di dubbio, nessuna consegna. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"},{"k":"case","s":"Un cliente vuole che la sua vicina ritiri un solo pacco in filiale durante le sue vacanze.","q":"Quale procura è la più adatta?","a":["Una procura unica per questo invio","Una procura permanente a pagamento","Nessuna, la vicina può ritirarlo liberamente","Una consegna in proprie mani"],"ex":"La procura unica copre un invio preciso; è gratuita per i privati. (Non nel materiale del corso.)","ref":"Non nel materiale del corso · Posta CH, «Procura alla Posta»"}]}];
window.LEVELS = [[0,"Stagista"],[150,"Apprendista in logistica"],[400,"Impiegato/a in logistica in formazione"],[800,"Impiegato/a in logistica AFC"],[1300,"Referente sicurezza"],[2000,"Esperto/a di protezione dei dati"],[3000,"Formatore/trice in logistica"]];
window.META = {"title":"M109 – Accesso e protezione dei dati","eyebrow":"Impiegato/a in logistica AFC · Modulo M109","key":"atelier-m109-acces-donnees-v1","intro":"Ripassi le autorizzazioni d’accesso, la sicurezza informatica, il segreto epistolare, il segreto postale, il segreto d’affari e la consegna degli invii alle persone giuste.","goal":20,"exam":{"n":24,"min":25},"cover":{"src":"img/cover.jpg","alt":"Immagine del titolo del corso M109: porta di una cassaforte davanti a rack di server"},"imgs":{"env":{"src":"img/enveloppes.it.png","alt":"Quattro buste indirizzate alla EnterSite AG: A solo l’azienda, B all’attenzione di Reto Gugger, C Signor Reto Gugger e poi l’azienda, D dicitura Personale/confidenziale"},"env_a":{"src":"img/env_a.it.png","alt":"Busta indirizzata alla EnterSite AG, Via Rigi 2, 5102 Rupperswil"},"env_b":{"src":"img/env_b.it.png","alt":"Busta indirizzata alla EnterSite AG, all’attenzione di Reto Gugger"},"env_c":{"src":"img/env_c.it.png","alt":"Busta indirizzata al Signor Reto Gugger, EnterSite AG"},"env_d":{"src":"img/env_d.it.png","alt":"Busta «Personale/confidenziale» indirizzata al Signor Reto Gugger, EnterSite AG"},"mail":{"src":"img/email_suspect.it.png","alt":"E-mail di un trasportatore sconosciuto che esige CHF 2.99 entro 24 ore, con un link verso un dominio .top"}},"icons":{"badge":"<rect x=\"5\" y=\"3\" width=\"14\" height=\"18\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"12\" cy=\"10\" r=\"2.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M8.5 16.5h7M10 3v2h4V3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>","lock":"<rect x=\"4.5\" y=\"10.5\" width=\"15\" height=\"10\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M8 10.5V7.5a4 4 0 0 1 8 0v3M12 14.5v2.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>","mailx":"<rect x=\"3\" y=\"5.5\" width=\"18\" height=\"13\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M3.5 6.5l8.5 6.5 8.5-6.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>","balance":"<path d=\"M12 4v16M7 20h10M5 7h14M5 7l-2.5 6a2.5 2.5 0 0 0 5 0L5 7zM19 7l-2.5 6a2.5 2.5 0 0 0 5 0L19 7z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>","parcel":"<path d=\"M12 3l8 4v10l-8 4-8-4V7l8-4zM4 7l8 4 8-4M12 11v10M8 5l8 4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>"},"note":{"text":"Il corso è del 2024. Dal 1° settembre 2023 in Svizzera si applica la nuova legge sulla protezione dei dati (nLPD); le regole di consegna degli invii (D5.3) provengono dalla Posta Svizzera e non figurano nel corso. Per i testi in vigore, consulti","url":"https://www.fedlex.admin.ch","link":"fedlex.admin.ch"},"langs":["fr","de","it"]};
